function openGroupSuggestions(suggestions,push=true){const box=$('#screen-content'),help=document.createElement('p');openScreen('Suggested Collections',()=>openGroupSuggestions(suggestions,false),push);box.replaceChildren();help.textContent='Nothing is moved automatically. Accept a suggestion to assign the Item, or dismiss it permanently.';box.append(help);for(const suggestion of suggestions){const row=document.createElement('article'),proposed=document.createElement('b'),text=document.createElement('p'),detail=document.createElement('small'),actions=document.createElement('div'),accept=document.createElement('button'),dismiss=document.createElement('button');row.className='card suggestion-row';proposed.textContent=`Suggested Collection: ${suggestion.group}`;text.textContent=suggestion.transcription;detail.textContent=`Heard identifier ${suggestion.candidate} · ${date(suggestion.createdAt)}`;actions.className='group-actions';accept.textContent='Accept';accept.className='primary';accept.onclick=()=>resolveGroupSuggestion(suggestion,'accept');dismiss.textContent='Dismiss';dismiss.onclick=()=>resolveGroupSuggestion(suggestion,'dismiss');actions.append(accept,dismiss);row.append(proposed,text,detail,actions);box.append(row)}}
