async function openGroupTimeline(name,push=true){const data=await(await req(`/api/collections/${encodeURIComponent(name)}/timeline`)).json(),box=$('#screen-content');timelineSaves=Promise.resolve();openScreen(data.group.name+(data.group.archived?' · archived':''),()=>openGroupTimeline(name,false),push);box.replaceChildren();const summary=document.createElement('p'),controls=document.createElement('div'),back=document.createElement('button');summary.textContent=`Chronological timeline · ${data.items.length} ${data.items.length===1?'Item':'Items'}`;controls.className='timeline-controls';for(const [format,label] of [['markdown','Markdown'],['json','JSON'],['zip','ZIP + audio']]){const button=document.createElement('button');button.textContent=label;button.onclick=()=>downloadGroupExport(data.group.name,format);controls.append(button)}back.textContent='Save & Back';back.className='primary';back.onclick=()=>saveTimelineAndBack(back);controls.append(back);box.append(summary,controls);if(!data.items.length){const empty=document.createElement('p');empty.className='empty';empty.textContent='This Collection has no Items.';box.append(empty)}for(const row of data.items)box.append(groupTimelineEntry(row))}
