function groupTimelineEntry(row){const card=document.createElement('article'),meta=document.createElement('div'),doneLabel=document.createElement('label'),done=document.createElement('input'),stamp=document.createElement('time'),category=document.createElement('select'),text=document.createElement('textarea'),tags=document.createElement('input'),compact=row.category==='task'||(!row.audio_path&&row.transcription.trim().length>0&&row.transcription.trim().length<=140);card.className='card timeline-entry';card.classList.toggle('checklist-item',compact);card.classList.toggle('completed',!!row.completed);meta.className='meta';done.type='checkbox';done.checked=!!row.completed;done.onchange=()=>{card.classList.toggle('completed',done.checked);queueTimelineSave(row.id,{completed:done.checked})};doneLabel.append(done,' Completed');stamp.textContent=date(row.recorded_at||row.created_at);for(const value of ['note','task','idea','question'])category.add(new Option(value,value));category.value=row.category;category.onchange=()=>queueTimelineSave(row.id,{category:category.value});meta.append(doneLabel,stamp,category);text.className='text';text.value=row.transcription;text.rows=compact?1:3;text.onchange=()=>queueTimelineSave(row.id,{transcription:text.value});tags.className='tags';tags.placeholder='tags, comma-separated';tags.value=row.tags;tags.onchange=()=>queueTimelineSave(row.id,{tags:tags.value});card.append(meta,text,tags);if(row.audio_path){const audio=document.createElement('audio'),download=document.createElement('button');audio.controls=true;download.textContent='Download audio';req(`/api/items/${row.id}/audio`).then(response=>response.blob()).then(blob=>{audio.src=URL.createObjectURL(blob);download.onclick=()=>{const link=document.createElement('a');link.href=audio.src;link.download=row.audio_path;link.click()}});card.append(audio,download)}return card}
