async function openActivity(push=true){openScreen('Recent activity',()=>openActivity(false),push);const box=$('#screen-content');box.innerHTML='<p class="empty">Loading activity…</p>';const activity=await(await req('/api/activity')).json();box.replaceChildren();if(!activity.length){box.innerHTML='<p class="empty">No activity yet.</p>';return}for(const item of activity){const row=document.createElement('article'),kind=document.createElement('b'),message=document.createElement('p'),stamp=document.createElement('time'),details=parseActivityDetails(item.details);row.className=`activity-row ${item.level||''}`;kind.textContent=item.kind.replaceAll('_',' ');message.textContent=item.message;stamp.textContent=date(item.created_at);row.append(kind,message);if(details?.reason){const reason=document.createElement('small');reason.textContent=`Why: ${details.reason}${Number.isFinite(details.confidence)?` · confidence ${Number(details.confidence).toFixed(2)}`:''}`;row.append(reason)}row.append(stamp);if(details?.confirmable&&details.receiptId){const confirm=document.createElement('button');confirm.textContent='Confirm operation';confirm.onclick=async()=>{confirm.disabled=true;try{await req(`/api/operations/${encodeURIComponent(details.receiptId)}/confirm`,{method:'POST'});await load();await openActivity(false)}catch(error){notice(error.message,'Confirmation failed');confirm.disabled=false}};row.append(confirm)}if(details?.reversible&&details.receiptId){const undo=document.createElement('button');undo.textContent='Undo';undo.onclick=async()=>{undo.disabled=true;try{await req(`/api/operations/${encodeURIComponent(details.receiptId)}/undo`,{method:'POST'});await load();await openActivity(false)}catch(error){notice(error.message,'Undo failed');undo.disabled=false}};row.append(undo)}box.append(row)}}
